#include <fstream>
#include <string>
#include "record.hpp"
#include "store.hpp"
int main(int argc,char**){if(argc>1)return 2;RecordStore store;store.add(Record{"test",1});std::ifstream in(PORTFOLIO_PATH);std::string text((std::istreambuf_iterator<char>(in)),{});auto has=[&](const char* value){return text.find(value)!=std::string::npos;};return store.size()==1&&has("build: cmake")&&has("test: ctest")&&has("benchmark: record-ingest")&&has("retrospective: ctest-argument")?0:1;}

